#!/usr/bin/env node

"use strict";

const daemon = require("daemon");
const fs = require("fs");
const parseArgs = require("minimist");

// COMMON

const common = require("./apply_common");
const exec = require("child_process").exec;
const syslog = common.syslog();
const work_state = common.work_state();

// GUI

const GUI = require("./gui");
const gui = new GUI();

// DUMMY

function doDummyInstall() {
    gui.setBackground(__dirname + "/Installer2.png");
    gui.setPercent(0);
    gui.incrementTo(0.33, 5.0, function() {
        gui.incrementTo(0.67, 5.0, function() {
            gui.setBackground(__dirname + "/Installer2a.png");
            gui.incrementTo(1.0, 5.0, function() {
                work_state.finishCurrent();
                if (work_state.current() !== null) {
                    do_work();
                } else {
                    console.log(JSON.stringify({}));
                    process.exit(0);
                }
            });
        });
    });
}

// DEFINE SUBSYSTEMS

const apply_bootloader = require("./apply_bootloader");
const apply_os = require("./apply_os");
const apply_services = require("./apply_services");
const apply_skill = require("./apply_skill");
const all_subsystems = [apply_bootloader, apply_os, apply_services, apply_skill];

// MAIN

let args = process.argv.slice(2);
const argopts = {
    string: ["source", "subsystem", "from", "to", "destination", "filter"],
    boolean: ["h", "help", "continue", "delay"]
};
let argv = parseArgs(args, argopts);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help                print this message");
    console.log("  --source FILE            update to install");
    console.log("  --subsystem SUBSYSTEM    subsystem to update");
    console.log("  --from VERSION           current version of the subsystem");
    console.log("  --to VERSION             updated version of the subsystem");
    console.log("  --destination PATH       where to install the update");
    console.log("  --filter STRING          filter for update queries");
    console.log("  --continue               resume update from stored state");
    console.log("  --delay                  inject delays for debugging");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (argv.delay) {
    common.delayReboot(true);
}

syslog.debug("Starting...");

process.on("uncaughtException", function(error) {
    syslog.error("Uncaught exception:", error.message);
    syslog.error(error.stack);
    throw(error);
});

/*
process.on("exit", function(code) {
    gui.cleanup();
});
*/

if (!argv.continue) {
    if (!argv.source) {
        console.log("ERROR: source not specified");
        usage();
        process.exit(1);
    }

    if (!argv.subsystem) {
        console.log("ERROR: subsystem not specified!");
        usage();
        process.exit(1);
    }

    if (!argv.from) {
        console.log("ERROR: from not specified!");
        usage();
        process.exit(1);
    }

    if (!argv.to) {
        console.log("ERROR: to not specified!");
        usage();
        process.exit(1);
    }

    if (!argv.destination) {
        console.log("ERROR: destination not specified!");
        usage();
        process.exit(1);
    }

    // empty filter string is allowed
    if (argv.filter === undefined) {
        console.log("ERROR: filter not specified!");
        usage();
        process.exit(1);
    }

    // if any are arrays, all must be arrays, of the same length
    let my_args = [argv.source, argv.subsystem, argv.from, argv.to, argv.destination, argv.filter];
    let any_array = false;
    let any_not_array = false;
    let array_len = 0;
    let any_different_len = false;
    for (let i=0; i<my_args.length; ++i) {
        if (Array.isArray(my_args[i])) {
            any_array = true;
            if (array_len == 0) {
                array_len = my_args[i].length;
            } else {
                if (my_args[i].length != array_len) {
                    any_different_len = true;
                }
            }
        } else {
            any_not_array = true;
        }
    }
    if ((any_array && any_not_array) || any_different_len) {
        console.log(
                "ERROR: arguments specified an inconsistent number of times!");
        usage();
        process.exit(1);
    }

    // build up the work state
    if (any_array) {
        for (let i=0; i<argv.source.length; ++i) {
            let ws = {
                source: argv.source[i],
                subsystem: argv.subsystem[i],
                step: null,
                from: argv.from[i],
                to: argv.to[i],
                destination: argv.destination[i],
                size: common.fileSize(argv.source[i]),
                filter: argv.filter[i]
            };
            work_state.addItem(ws);
        }
    } else {
        let ws = {
            source: argv.source,
            subsystem: argv.subsystem,
            step: null,
            from: argv.from,
            to: argv.to,
            destination: argv.destination,
            size: common.fileSize(argv.source),
            filter: argv.filter
        };
        work_state.addItem(ws);
    }

    // save and reboot to actually start
    try {
        work_state.saveSync(common.work_state_file);
    } catch (error) {
        console.log("ERROR: cannot save work state!");
        process.exit(1);
    }
    common.reboot(function() { process.exit(0); });
} else { // continue
    try {
        work_state.loadSync(common.work_state_file);
    } catch (error) {
        // XXX work state is broken, but we're in OTA mode
        syslog.error("Unrecoverable Work State Error:", error.message);
        syslog.error(error.stack);
        throw(error);
    }

    function finalVerifyFunc() {
        // spin to the background so system manager can start up
        daemon();

        const timeout_secs = 60.0;
        syslog.info("Begin final verify");

        common.waitForSysMgrRecord(timeout_secs, function(record) {
            if (record) {
                syslog.debug("record: %s", JSON.stringify(record));
                syslog.info("Services are running!");
                fs.unlink(common.work_state_file, function(error) {
                    if (error) {
                        common.fail(error);
                    } else {
                        exec("sync", function(error, stdout, stderr) {
                            if (error) {
                                common.fail(error);
                            } else {
                                // clean up temp dir
                                common.cleanScratchDir(common.scratch_dir,
                                        function() {
                                    // we are really, really done
                                    process.exit(0);
                                });
                            }
                        });
                    }
                });
            } else {
                // give up
                syslog.error("Service verification failed!");
                work_state.retryAll();
                work_state.save(common.work_state_file, function(error) {
                    if (error) {
                        // XXX what can we do here?
                        common.fail(error);
                    } else {
                        common.reboot(function() { process.exit(0); });
                    }
                });
            }
        });
    }

    function do_work() {
        const ws = work_state.current();
        if (ws === null) {
            // we are at the end of all updates. do sanity checks
            finalVerifyFunc();
            return;
        }
        syslog.info("Continue: source=%s, subsystem=%s, step=%s",
                ws.source, ws.subsystem, ws.step);
        if (ws.subsystem == "dummy") {
            doDummyInstall();
            return;
        }
        let handled = false;
        all_subsystems.forEach(function(value, index, array) {
            if (!handled && value.handlesSubsystem(ws.subsystem)) {
                value.execute(ws.step, work_state, gui);
                handled = true;
            }
        });
        if (!handled) {
            console.log("ERROR: unsupported subsystem '" + ws.subsystem + "'");
            usage();
            process.exit(1);
        }
    }

    function next_func() {
        // save work state so we know the previous update completed
        work_state.save(common.work_state_file, function(error) {
            if (error) {
                // XXX what can we do here?
                common.fail(error);
            } else {
                syslog.info("Chain to next update...");
                do_work();
            }
        });
    }

    common.setNextFunction(next_func);

    try {
        do_work();
    } catch (error) {
        syslog.error("Unhandled Error:", error.message);
        syslog.error(error.stack);
        // XXX retry?
        throw(error);
    }
}
